import{_ as a,o as t,c as r,a as s,e as i}from"./chunks/framework.Cq4gzU1W.js";const h=JSON.parse('{"title":"Scratch","description":"Scratch un lenguaje de programación divertido","frontmatter":{"title":"Scratch ","description":"Scratch un lenguaje de programación divertido","weight":10,"draft":false,"icon":"fas fa-bug"},"headers":[],"relativePath":"scratch/estructuras-repetitivas/index.md","filePath":"04_Scratch/05_Repetitivas/index.md"}'),c={name:"scratch/estructuras-repetitivas/index.md"};function o(n,e,u,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s("p",{"{:::":""},"{{::: objetivos}} Acceder a scratch para programar Ver el entorno de ejecución",-1),i('<h1 id="estructuras-repetitivas" tabindex="-1">Estructuras repetitivas <a class="header-anchor" href="#estructuras-repetitivas" aria-label="Permalink to &quot;Estructuras repetitivas&quot;">​</a></h1><h1 id="estructuras-repetitivas-1" tabindex="-1">Estructuras repetitivas <a class="header-anchor" href="#estructuras-repetitivas-1" aria-label="Permalink to &quot;Estructuras repetitivas&quot;">​</a></h1><p>Hasta ahora hemos aprendido a ejecutar instrucciones de forma secuencial y a tomar decisiones mediante estructuras selectivas.</p><p>Pero ¿qué ocurre cuando necesitamos <strong>realizar una misma acción varias veces</strong>?</p><p>Imaginemos que queremos que un personaje avance 10 pasos, 20 veces. Podríamos escribir 20 instrucciones iguales, pero sería poco práctico.</p><p>Para resolver este problema utilizamos las <strong>estructuras repetitivas</strong>, también llamadas <strong>bucles</strong>.</p><p>Un bucle permite ejecutar un conjunto de instrucciones varias veces, sin necesidad de escribirlas repetidamente.</p><p>En Scratch encontramos tres formas habituales de repetición:</p><ul><li>🔁 <strong>Repetición indefinida:</strong> ejecuta continuamente las instrucciones mientras el programa siga funcionando.</li><li>🔢 <strong>Repetición con contador:</strong> ejecuta las instrucciones un número determinado de veces.</li><li>🔀 <strong>Repetición con condición:</strong> repite las instrucciones hasta que se cumple una condición.</li></ul><p>Por ejemplo:</p><ul><li>🚶 Avanzar 10 pasos, 5 veces.</li><li>⏰ Actualizar continuamente un reloj.</li><li>🎮 Mover un personaje hasta que toque el borde.</li><li>🚀 Realizar una cuenta atrás desde 10 hasta 0.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Idea fundamental</p><p>Las estructuras repetitivas permiten <strong>automatizar acciones que deben ejecutarse varias veces</strong>.</p><p>En lugar de repetir las instrucciones en nuestro código, indicamos <strong>qué acciones queremos repetir y cuándo debe terminar la repetición</strong>.</p><p>En Scratch utilizaremos los bloques <code>repetir</code>, <code>por siempre</code> y <code>repetir hasta que</code>.</p><p>Más adelante, en PHP, utilizaremos estructuras como <code>for</code>, <code>while</code>, <code>do...while</code> y <code>foreach</code>.</p></div><h2 id="estudio-en-scratch" tabindex="-1">Estudio en scratch <a class="header-anchor" href="#estudio-en-scratch" aria-label="Permalink to &quot;Estudio en scratch&quot;">​</a></h2><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?curid=6652" width="100%" height="10197">WikiEducator </iframe></div>',14)])])}const v=a(c,[["render",o]]);export{h as __pageData,v as default};
